// === EXTRACT ARTICLES ===
// Trouve la section sectionConsultee=true et collecte tous les articles récursivement

const resp = $input.first().json;
const body = resp.body || resp;
const sections = body.sections || [];
const today = new Date().toISOString().split('T')[0];

// Trouver la section consultée
function findConsultee(sections) {
  for (const s of sections) {
    if (s.sectionConsultee) return s;
    if (s.sections) {
      const found = findConsultee(s.sections);
      if (found) return found;
    }
  }
  return null;
}

// Collecter les articles récursivement
function collectArticles(section, path = []) {
  const currentPath = [...path, (section.title || '').trim()];
  const results = [];

  if (section.articles) {
    for (const a of section.articles) {
      if (a.content && a.etat && a.etat.startsWith('VIGUEUR')) {
        results.push({
          legifrance_id: a.id,
          legifrance_cid: a.cid || '',
          num: a.num || '',
          etat: a.etat,
          content_html: a.content,
          content_text: stripHtml(a.content),
          nota: a.nota || '',
          date_debut: a.dateDebut || null,
          section_path: currentPath,
          container_title: null,
          consult_date: today,
          source_type: 'CODE',
          source_legifrance_id: 'LEGITEXT000006072050'
        });
      }
    }
  }

  if (section.sections) {
    for (const sub of section.sections) {
      results.push(...collectArticles(sub, currentPath));
    }
  }
  return results;
}

// Strip HTML → texte brut
function stripHtml(html) {
  return (html || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const consultee = findConsultee(sections);
if (!consultee) {
  throw new Error('Aucune section sectionConsultee=true trouvée');
}

const articles = collectArticles(consultee);

return [{
  json: {
    sectionTitle: (consultee.title || '').trim(),
    sectionId: consultee.id,
    totalArticles: articles.length,
    consultDate: today,
    articles: articles
  }
}];

// === ENSURE SOURCE EXISTS IN SUPABASE ===
const supabaseUrl = "https://hgczhihoauceapvteahz.supabase.co";
const serviceKey = "JWT_REMPLACER";
const data = $input.first().json;

// Upsert la source 'Code du travail'
const sourceResp = await this.helpers.httpRequest({
