  const batch = articles.slice(i,i+BATCH_SIZE).map(a=>({
    source_id:sourceId, legifrance_id:a.legifrance_id, legifrance_cid:a.legifrance_cid, num:a.num,
    content_html:a.content_html, content_text:a.content_text, nota:a.nota||null, etat:a.etat,
    date_debut: (a.date_debut ? (typeof a.date_debut==='number' ? new Date(a.date_debut).toISOString().split('T')[0] : String(a.date_debut).split('T')[0]) : null),
    section_path:a.section_path, container_title:a.container_title||null, consult_date:consultDate, ingestion_run_id:runId }));
  try {
    await this.helpers.httpRequest({ method:'POST', url:`${supabaseUrl}/rest/v1/legal_articles?on_conflict=source_id,legifrance_id`,
      headers:{'Authorization':`Bearer ${serviceKey}`,'apikey':serviceKey,'Content-Type':'application/json','Prefer':'resolution=merge-duplicates'},
      body: JSON.stringify(batch), returnFullResponse:false });
    upserted += batch.length;
  } catch(err){ errors += batch.length; console.log('Supabase batch error:', err.message); }
}
const status = errors===0?'SUCCESS':(upserted>0?'PARTIAL':'FAILED');
await this.helpers.httpRequest({ method:'PATCH', url:`${supabaseUrl}/rest/v1/ingestion_runs?id=eq.${runId}`,
  headers:{'Authorization':`Bearer ${serviceKey}`,'apikey':serviceKey,'Content-Type':'application/json'},
  body: JSON.stringify({ status, completed_at:new Date().toISOString(), articles_upserted:upserted, error_message: errors>0?(errors+' articles en erreur'):null }), returnFullResponse:false });




