// Agrege toutes les pages ACCO (filtre IDCC 2378), dedup
const items = $input.all();
const today = new Date().toISOString().split('T')[0];
function stripHtml(h){ return String(h||'').replace(/<[^>]+>/g,' ').replace(/<mark>/gi,'').replace(/&[a-z]+;/gi,' ').replace(/\s+/g,' ').trim(); }
const seen = new Set();
const accords = [];
for (const it of items) {
  const body = it.json.body || it.json;
  const results = (body && body.results) || [];
  for (const r of results) {
    const id = r.titles && r.titles[0] && r.titles[0].id;
    if (!id || seen.has(id)) continue;
    seen.add(id);
    accords.push({ legifrance_id:id, titre:stripHtml(r.titles[0].title||''), texte_excerpt:stripHtml(r.text||'').substring(0,5000), nature:r.nature||'', idcc:r.idcc||'2378', consult_date:today });
  }
}
return [{ json: { accords, totalAccords: accords.length, consultDate: today } }];

